# hypothesis: Overloads are tried in declaration order, so a Literal overload listed first wins for the literal argument, a plain str falls through to the broader str overload, and a generic overload returns the list element type.
from typing import Literal, TypeVar, assert_type, overload, reveal_type

T = TypeVar('T')


@overload
def mode(flag: Literal['fast']) -> int: ...
@overload
def mode(flag: str) -> str: ...
@overload
def mode(flag: int | None) -> float: ...
def mode(flag: int | str | None) -> int | str | float:
    if flag == 'fast':
        return 1
    if isinstance(flag, str):
        return flag.upper()
    if flag is None:
        return 0.5
    return float(flag)


@overload
def first(items: list[T]) -> T | None: ...
@overload
def first(items: list[T], default: T) -> T: ...
def first(items: list[T], default: T | None = None) -> T | None:
    return items[0] if items else default


a = mode('fast')
assert_type(a, int)
b = mode('slow')
assert_type(b, str)
assert b == 'SLOW'
c = mode(None)
assert_type(c, float)
d = mode(3)
assert d == 3.0
e = first([10, 20])
reveal_type(e)
assert e == 10
f = first([], 'none')
assert_type(f, str)
assert f == 'none'
